<?php
declare(strict_types=1);
require __DIR__.'/app/bootstrap.php';
$orderNumber=trim(scalar_string($_GET['order']??''));$phone=normalize_phone(scalar_string($_GET['phone']??''));$shipment=null;$events=[];$smsDeliveryNotices=[];$error='';
if($orderNumber!==''||$phone!==''){
    rate_limit('public-tracking',20,600);
    if(!preg_match('/^[A-Za-z0-9-]{5,50}$/',$orderNumber)||!preg_match('/^09\d{9}$/',$phone))$error='شماره سفارش و موبایل را کامل وارد کنید.';
    else{$stmt=db()->prepare('SELECT s.*,o.id order_id,o.order_number,o.customer_name,o.order_status,o.payment_status,c.name carrier_name,c.tracking_url_template FROM shipments s JOIN orders o ON o.id=s.order_id LEFT JOIN shipping_carriers c ON c.id=s.carrier_id WHERE o.order_number=? AND o.phone=? LIMIT 1');$stmt->execute([$orderNumber,$phone]);$shipment=$stmt->fetch()?:null;if(!$shipment)$error='پرونده ارسالی با این مشخصات پیدا نشد.';else{$stmt=db()->prepare('SELECT status,event_text,location,created_at FROM shipment_events WHERE shipment_id=? ORDER BY id DESC');$stmt->execute([(int)$shipment['id']]);$events=$stmt->fetchAll();$smsDeliveryNotices=sms_customer_order_delivery_notices((int)$shipment['order_id'],true);}}
}
$pageKey='tracking';$pageTitle='رهگیری سفارش | '.setting('store_name');$robots='noindex,nofollow';$headExtra='<link rel="stylesheet" href="'.e(asset('css/store-v200.css')).'">';require BASE_PATH.'/app/views/header.php';
?>
<main><section class="page-hero"><div class="container"><h1>رهگیری سفارش</h1><p>وضعیت بسته و آخرین رویدادهای ارسال را مشاهده کنید.</p></div></section><div class="container product-page"><form method="get" class="checkout-card"><div class="form-grid"><div class="field"><label>شماره سفارش</label><input name="order" dir="ltr" maxlength="50" value="<?=e($orderNumber)?>" required></div><div class="field"><label>شماره موبایل سفارش</label><input name="phone" inputmode="numeric" pattern="09[0-9]{9}" maxlength="11" value="<?=e($phone)?>" required></div></div><button class="btn btn-primary">نمایش وضعیت</button></form><?php foreach(flashes() as $flash):?><div class="form-message <?=$flash['type']==='success'?'success':'error'?>" style="margin:10px 0"><?=e($flash['message'])?></div><?php endforeach?><?php if($error):?><div class="form-error"><?=e($error)?></div><?php endif?><?php if($shipment):$trackingUrl=shipment_tracking_url($shipment['tracking_url_template']??null,(string)$shipment['tracking_code']);?><div class="checkout-card"><h2>سفارش <?=e($shipment['order_number'])?></h2><div class="order-meta"><div><strong>شرکت حمل</strong><br><?=e($shipment['carrier_name']?:'حمل فروشگاه')?></div><div><strong>کد رهگیری</strong><br><span dir="ltr"><?=e($shipment['tracking_code']?:'ثبت نشده')?></span></div><div><strong>وضعیت</strong><br><?=e(shipment_status_labels()[$shipment['status']]??$shipment['status'])?></div></div><?php if($trackingUrl):?><a class="btn btn-secondary" href="<?=e($trackingUrl)?>" target="_blank" rel="noopener noreferrer">رهگیری در سایت شرکت حمل</a><?php endif?></div><?php if($smsDeliveryNotices):?><div class="checkout-card"><h2>وضعیت پیامک‌ها</h2><?php foreach($smsDeliveryNotices as $smsNotice):?><div class="form-message <?=$smsNotice['level']==='success'?'success':($smsNotice['level']==='error'?'error':'')?>" style="margin:10px 0"><strong><?=e($smsNotice['event_label'].' — '.$smsNotice['title'])?></strong><br><?=e($smsNotice['message'])?><?php if($smsNotice['solution']!==''):?><br><small><b>راهکار:</b> <?=e($smsNotice['solution'])?></small><?php endif?></div><?php if(sms_notice_is_blacklisted($smsNotice)&&sms_order_event_can_be_resent((string)$smsNotice['event_key'],$shipment)):?><?=sms_blacklist_release_guide_html(['resend_fields'=>['track_order'=>$orderNumber,'track_phone'=>$phone,'event_key'=>$smsNotice['event_key'],'return_to'=>$_SERVER['REQUEST_URI']??app_url('track-order.php')],'change_url'=>app_url('contact.php'),'change_label'=>'اصلاح شماره با پشتیبانی'])?><?php endif?><?php endforeach?></div><?php endif?><div class="checkout-card"><h2>رویدادهای ارسال</h2><div class="timeline"><?php foreach($events as $event):?><div class="timeline-item"><strong><?=e(shipment_status_labels()[$event['status']]??$event['status'])?></strong><p><?=e($event['event_text'])?><?=e($event['location']?' — '.$event['location']:'')?></p><small><?=e(jalali_format($event['created_at']))?></small></div><?php endforeach?></div></div><?php endif?></div></main>
<?php require BASE_PATH.'/app/views/footer.php';
